-- 541: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 3 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_541_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_541_guard;
INSERT INTO _migration_541_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_011' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the complement of an angle of 35°.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 145°","B. 65°","C. 55°","D. 325°"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Complementary angles sum to 90°, so the complement of 35° is 90° − 35° = 55°. (145° is the supplement 180° − 35°, the wrong angle pair.) Therefore the correct answer is C: 55°.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_011' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_541_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_012' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The perimeter of a square is 36 cm. Find the length of one side.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6 cm","B. 12 cm","C. 18 cm","D. 9 cm"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A square has four equal sides, so each side is 36 ÷ 4 = 9 cm. (6 cm divides by 6 instead of 4; 18 cm halves the perimeter.) Therefore the correct answer is D: 9 cm.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_012' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_541_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_013' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the size of each interior angle of a regular pentagon.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 108°","B. 120°","C. 72°","D. 540°"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A pentagon has interior-angle sum (5 − 2) × 180° = 540°. A regular pentagon has five equal angles, so each is 540° ÷ 5 = 108°. (72° is the exterior angle; 120° belongs to a regular hexagon.) Therefore the correct answer is A: 108°.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_013' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_541_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_014' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An isosceles triangle has a vertex angle of 40°. Calculate the size of each base angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 140°","B. 70°","C. 40°","D. 100°"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The base angles of an isosceles triangle are equal, and all three angles sum to 180°: each base angle is (180° − 40°) ÷ 2 = 140° ÷ 2 = 70°. (140° forgets the division by 2.) Therefore the correct answer is B: 70°.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_014' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_541_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_015' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Two parallel lines are cut by a transversal. If one of a pair of co-interior angles is 110°, find the other co-interior angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 110°","B. 90°","C. 70°","D. 20°"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Co-interior (allied) angles between parallel lines are supplementary: 180° − 110° = 70°. (110° would be correct for corresponding or alternate angles, not co-interior ones.) Therefore the correct answer is C: 70°.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_015' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_011', 'topic_wassce_p2_math_geo', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the complement of an angle of 35°.', 'multiple_choice', NULL, '["A. 145°","B. 65°","C. 55°","D. 325°"]', 'C', 'Complementary angles sum to 90°, so the complement of 35° is 90° − 35° = 55°. (145° is the supplement 180° − 35°, the wrong angle pair.) Therefore the correct answer is C: 55°.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO1', NULL, NULL, 'board_waec');
